    DescribeBatchPredictionsInput.add_member(:prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: ComparatorValue, location_name: 'Prefix', traits: {"smithy.api#documentation" => "<p>A string that is found at the beginning of a variable, such as <code>Name</code> or <code>Id</code>.</p> \n        <p>For example, a <code>Batch Prediction</code> operation could have the <code>Name</code> \n            <code>2014-09-09-HolidayGiftMailer</code>. To search for \n            this <code>BatchPrediction</code>, select <code>Name</code> for the <code>FilterVariable</code> and any of the following strings for the \n            <code>Prefix</code>:\n        </p>\n        \n        <ul>\n            <li>\n               <p>2014-09</p>\n            </li>\n            <li>\n               <p>2014-09-09</p>\n            </li>\n            <li>\n               <p>2014-09-09-Holiday</p>\n            </li>\n         </ul>"}))
