    GetMLModelOutput.add_member(:training_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingParameters, location_name: 'TrainingParameters', traits: {"smithy.api#documentation" => "<p>A list of the training parameters in the <code>MLModel</code>. The list is implemented as\n            a map of key-value pairs.</p>\n        <p>The following is the current set of training parameters:</p>\n        <ul>\n            <li>\n               <p>\n                  <code>sgd.maxMLModelSizeInBytes</code> - The maximum allowed size of the model. Depending on the\n                    input data, the size of the model might affect its performance.</p> \n                <p> The value is an integer that ranges from <code>100000</code> to <code>2147483648</code>. The default value is <code>33554432</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>sgd.maxPasses</code> - The number of times that the training process traverses the\n                    observations to build the <code>MLModel</code>. The value is an integer that\n                    ranges from <code>1</code> to <code>10000</code>. The default value is\n                        <code>10</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>sgd.shuffleType</code> - Whether Amazon ML shuffles the training data. Shuffling data improves a\n                    model's ability to find the optimal solution for a variety of data types. The\n                    valid values are <code>auto</code> and <code>none</code>. The default value is\n                        <code>none</code>. We strongly recommend that you shuffle your data.</p>\n            </li>\n            <li>\n               <p>\n                  <code>sgd.l1RegularizationAmount</code> - The coefficient regularization L1 norm. It controls\n                    overfitting the data by penalizing large coefficients. This tends to drive\n                    coefficients to zero, resulting in a sparse feature set. If you use this\n                    parameter, start by specifying a small value, such as <code>1.0E-08</code>.</p>\n                <p>The value is a double that ranges from <code>0</code> to <code>MAX_DOUBLE</code>.\n                    The default is to not use L1 normalization. This parameter can't be used when\n                        <code>L2</code> is specified. Use this parameter sparingly.</p>\n            </li>\n            <li>\n               <p>\n                  <code>sgd.l2RegularizationAmount</code> - The coefficient regularization L2 norm. It controls\n                    overfitting the data by penalizing large coefficients. This tends to drive\n                    coefficients to small, nonzero values. If you use this parameter, start by\n                    specifying a small value, such as <code>1.0E-08</code>.</p>\n                <p>The value is a double that ranges from <code>0</code> to <code>MAX_DOUBLE</code>.\n                    The default is to not use L2 normalization. This parameter can't be used when\n                        <code>L1</code> is specified. Use this parameter sparingly.</p>\n            </li>\n         </ul>"}))
    GetMLModelOutput.add_member(:input_data_location_s3, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Url, location_name: 'InputDataLocationS3', traits: {"smithy.api#documentation" => "<p>The location of the data file or directory in Amazon Simple Storage Service (Amazon S3).</p>"}))
    GetMLModelOutput.add_member(:ml_model_type, Smithy::Schema::Shapes::ShapeRef.new(shape: MLModelType, location_name: 'MLModelType', traits: {"smithy.api#documentation" => "<p>Identifies the <code>MLModel</code> category. The following are the available types: </p>\n        <ul>\n            <li>\n               <p>REGRESSION -- Produces a numeric result. For example, \"What price should a house be listed at?\"</p>\n            </li>\n            <li>\n               <p>BINARY -- Produces one of two possible results. For example, \"Is this an e-commerce website?\"</p>\n            </li>\n            <li>\n               <p>MULTICLASS -- Produces one of several possible results. For example, \"Is this a HIGH, LOW or MEDIUM risk trade?\"</p>\n            </li>\n         </ul>"}))
    GetMLModelOutput.add_member(:score_threshold, Smithy::Schema::Shapes::ShapeRef.new(shape: ScoreThreshold, location_name: 'ScoreThreshold', traits: {"smithy.api#documentation" => "<p>The scoring threshold is used in binary classification <code>MLModel</code>\n            models. It marks the boundary between a positive prediction and a\n            negative prediction.</p>\n        <p>Output values greater than or equal to the threshold receive a positive result from the MLModel, such as \n            <code>true</code>. Output values less than the threshold receive a negative response from the MLModel, \n            such as <code>false</code>.</p>"}))
    GetMLModelOutput.add_member(:score_threshold_last_updated_at, Smithy::Schema::Shapes::ShapeRef.new(shape: EpochTime, location_name: 'ScoreThresholdLastUpdatedAt', traits: {"smithy.api#documentation" => "<p>The time of the most recent edit to the <code>ScoreThreshold</code>. The time is expressed in epoch time.</p>"}))
    GetMLModelOutput.add_member(:log_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: PresignedS3Url, location_name: 'LogUri', traits: {"smithy.api#documentation" => "<p>A link to the file that contains logs of the <code>CreateMLModel</code> operation.</p>"}))
    GetMLModelOutput.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: Message, location_name: 'Message', traits: {"smithy.api#documentation" => "<p>A description of the most recent details about accessing the <code>MLModel</code>.</p>"}))
    GetMLModelOutput.add_member(:compute_time, Smithy::Schema::Shapes::ShapeRef.new(shape: LongType, location_name: 'ComputeTime', traits: {"smithy.api#documentation" => "<p>The approximate CPU time in milliseconds that Amazon Machine Learning spent processing the <code>MLModel</code>, normalized and scaled on computation resources. <code>ComputeTime</code> is only available if the <code>MLModel</code> is in the <code>COMPLETED</code> state.</p>"}))
    GetMLModelOutput.add_member(:finished_at, Smithy::Schema::Shapes::ShapeRef.new(shape: EpochTime, location_name: 'FinishedAt', traits: {"smithy.api#documentation" => "<p>The epoch time when Amazon Machine Learning marked the <code>MLModel</code> as <code>COMPLETED</code> or <code>FAILED</code>. <code>FinishedAt</code> is only available when the <code>MLModel</code> is in the <code>COMPLETED</code> or <code>FAILED</code> state.</p>"}))
    GetMLModelOutput.add_member(:started_at, Smithy::Schema::Shapes::ShapeRef.new(shape: EpochTime, location_name: 'StartedAt', traits: {"smithy.api#documentation" => "<p>The epoch time when Amazon Machine Learning marked the <code>MLModel</code> as <code>INPROGRESS</code>. <code>StartedAt</code> isn't available if the <code>MLModel</code> is in the <code>PENDING</code> state.</p>"}))
    GetMLModelOutput.add_member(:recipe, Smithy::Schema::Shapes::ShapeRef.new(shape: Recipe, location_name: 'Recipe', traits: {"smithy.api#documentation" => "<p>The recipe to use when training the <code>MLModel</code>. The <code>Recipe</code>\n            provides detailed information about the observation data to use during training, and\n            manipulations to perform on the observation data during training.</p>\n        <p>\n            <b>Note:</b> This parameter is provided as part of the verbose format.</p>"}))
