    RDSDataSpec.add_member(:subnet_id, Smithy::Schema::Shapes::ShapeRef.new(shape: EDPSubnetId, location_name: 'SubnetId', traits: {"smithy.api#documentation" => "<p>The subnet ID to be used to access a VPC-based RDS DB instance. This attribute is used by Data Pipeline to carry out the copy task from Amazon RDS to Amazon S3.</p>", "smithy.api#required" => {}}))
    RDSDataSpec.add_member(:security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: EDPSecurityGroupIds, location_name: 'SecurityGroupIds', traits: {"smithy.api#documentation" => "<p>The security group IDs to be used to access a VPC-based RDS DB instance. Ensure that there are appropriate ingress rules set up to allow access to the RDS DB instance. This attribute is used by Data Pipeline to carry out the copy operation from Amazon RDS to an Amazon S3 task.</p>", "smithy.api#required" => {}}))
