    RealtimeEndpointInfo.add_member(:endpoint_status, Smithy::Schema::Shapes::ShapeRef.new(shape: RealtimeEndpointStatus, location_name: 'EndpointStatus', traits: {"smithy.api#documentation" => "<p> The current status of the real-time endpoint for the <code>MLModel</code>. This element can have one of the following values: </p>\n        <ul>\n            <li>\n               <p>\n                  <code>NONE</code>  - Endpoint does not exist or was previously deleted.</p>\n            </li>\n            <li>\n               <p>\n                  <code>READY</code> - Endpoint is ready to be used for real-time predictions.</p>\n            </li>\n            <li>\n               <p>\n                  <code>UPDATING</code> - Updating/creating the endpoint. </p>\n            </li>\n         </ul>"}))
